import { createHash, randomBytes } from 'node:crypto';
import * as fs from 'node:fs';
import * as fsp from 'node:fs/promises';
import * as path from 'node:path';
import { responseCandidates } from './api.js';
import { isRecord, PublisherError } from './util.js';
import { readZip } from './zip.js';
const MAX_PACKAGE_BYTES = 20 * 1024 * 1024;
const MAX_UNCOMPRESSED_BYTES = 100 * 1024 * 1024;
const MAX_FILES = 2_000;
const ITEM_ID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SAFE_SLUG_RE = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;
const SHA256_RE = /^[0-9a-f]{64}$/;
export function marketplaceItems(response) {
    const raw = Array.isArray(response.data) ? response.data : Array.isArray(response.items) ? response.items : [];
    return raw.filter(isRecord).map(normalizeMarketplaceItem);
}
export function marketplaceItem(response) {
    for (const candidate of responseCandidates(response)) {
        if (firstString(candidate, 'id', 'itemId', 'item_id'))
            return normalizeMarketplaceItem(candidate);
    }
    throw new PublisherError('Marketplace response does not contain an item.', 'invalid_marketplace_response');
}
export function normalizeMarketplaceItem(item) {
    const metadata = record(item.metadata);
    const publisher = record(metadata.publisher);
    const offer = record(item.installOffer ?? item.install_offer ?? metadata.taku_install_offer);
    const latest = record(item.latestVersion ?? item.latest_version);
    const type = firstString(item, 'type', 'kind').toLowerCase();
    const displayKind = firstString(item, 'displayKind', 'display_kind')
        || firstString(offer, 'displayKind', 'display_kind')
        || type;
    const installability = firstString(item, 'installability')
        || firstString(offer, 'installability');
    return {
        item_id: firstString(item, 'id', 'itemId', 'item_id'),
        name: firstString(item, 'name', 'title'),
        slug: firstString(item, 'slug'),
        type,
        status: firstString(item, 'status').toLowerCase(),
        short_description: firstString(item, 'shortDescription', 'short_description'),
        description: firstString(item, 'description'),
        creator: firstString(item, 'creatorDisplayName', 'creator_display_name', 'creatorUsername', 'creator_username'),
        version: firstPositiveInt(latest.versionNumber, latest.version_number, item.currentVersion, item.current_version),
        install_count: firstNonnegativeInt(item.installCount, item.install_count),
        categories: strings(item.categories),
        tags: strings(item.tags),
        platforms: strings(item.platforms),
        installability,
        display_kind: displayKind,
        cta: firstString(offer, 'cta'),
        deep_link: firstString(offer, 'deepLink', 'deep_link'),
        external_url: firstString(item, 'externalUrl', 'external_url')
            || firstString(offer, 'externalUrl', 'external_url'),
        codex_install_supported: type === 'skill' && displayKind === 'skill',
        configuration_requirements: requirementsFromSources(latest, publisher, metadata),
    };
}
export function installPreflight(response, itemId, installRoot) {
    const contract = installContract(response);
    const item = record(contract.item);
    const normalized = normalizeMarketplaceItem({ ...item, latestVersion: contract.latestVersion ?? contract.latest_version });
    validateItemId(itemId);
    if (normalized.item_id !== itemId)
        throw new PublisherError('Install package item ID does not match the requested item.', 'install_item_mismatch');
    if (normalized.type !== 'skill')
        throw new PublisherError('This development installer currently supports Codex Skills only.', 'unsupported_install_type', { type: normalized.type });
    if (normalized.status !== 'published')
        throw new PublisherError('Only published Marketplace Skills can be installed.', 'marketplace_item_not_published');
    const access = record(contract.access);
    if (access.allowed !== true)
        throw new PublisherError('This account does not have access to the Marketplace Skill.', 'marketplace_access_denied', { reason: firstString(access, 'reason') });
    const slug = String(normalized.slug ?? '');
    if (!SAFE_SLUG_RE.test(slug))
        throw new PublisherError('Marketplace Skill has an unsafe install slug.', 'unsafe_install_slug');
    const packageRecord = record(contract.package ?? contract.installPackage);
    const version = firstPositiveInt(packageRecord.versionNumber, packageRecord.version_number, normalized.version);
    if (version === null)
        throw new PublisherError('Marketplace Skill has no installable version.', 'package_not_available');
    const expectedSha256 = firstString(packageRecord, 'contentHash', 'content_hash').toLowerCase();
    if (!SHA256_RE.test(expectedSha256))
        throw new PublisherError('Marketplace Skill package does not have a verifiable SHA-256.', 'missing_package_hash');
    const downloadUrl = firstString(contract, 'downloadUrl', 'download_url');
    if (!downloadUrl)
        throw new PublisherError('Marketplace Skill package is not available for download.', 'package_not_available');
    const destination = safeDestination(installRoot, slug);
    return {
        item: normalized,
        version,
        expected_sha256: expectedSha256,
        expected_size: firstPositiveInt(packageRecord.fileSizeBytes, packageRecord.file_size_bytes),
        download_url: downloadUrl,
        install_root: path.resolve(installRoot),
        target_dir: destination,
    };
}
export async function installCodexSkill(client, response, options) {
    const preflight = installPreflight(response, options.itemId, options.installRoot);
    if (!options.confirmItemId || options.confirmItemId !== options.itemId)
        throw new PublisherError('Install confirmation must exactly match the selected item ID.', 'install_confirmation_mismatch');
    const destination = String(preflight.target_dir);
    if (fs.existsSync(destination))
        throw new PublisherError('A Codex Skill with this Marketplace slug already exists. This installer will not overwrite it.', 'install_target_exists', { target_dir: destination });
    const packageBytes = await client.downloadPublicPackage(String(preflight.download_url), MAX_PACKAGE_BYTES);
    const actualSha256 = createHash('sha256').update(packageBytes).digest('hex');
    if (actualSha256 !== preflight.expected_sha256)
        throw new PublisherError('Marketplace Skill package SHA-256 does not match the server contract.', 'package_hash_mismatch');
    if (preflight.expected_size !== null && Number(preflight.expected_size) !== packageBytes.length)
        throw new PublisherError('Marketplace Skill package size does not match the server contract.', 'package_size_mismatch');
    await extractSkillAtomically(packageBytes, destination);
    let warning = null;
    try {
        await client.recordMarketplaceInstall(options.itemId, Number(preflight.version));
    }
    catch (error) {
        if (!(error instanceof PublisherError))
            throw error;
        warning = { code: error.code, message: error.message };
    }
    const item = record(preflight.item);
    return {
        status: warning ? 'installed_with_record_warning' : 'installed',
        item,
        version: preflight.version,
        target_dir: destination,
        sha256: actualSha256,
        configuration_requirements: item.configuration_requirements,
        install_record_warning: warning,
        next_action: 'start_new_codex_task',
    };
}
async function extractSkillAtomically(packageBytes, destination) {
    await fsp.mkdir(path.dirname(destination), { recursive: true });
    const temporary = path.join(path.dirname(destination), `.${path.basename(destination)}.install-${randomBytes(6).toString('hex')}`);
    await fsp.mkdir(temporary, { mode: 0o700 });
    let moved = false;
    try {
        const entries = validateEntries(readZip(packageBytes));
        for (const entry of entries) {
            const target = path.join(temporary, ...entry.name.split('/'));
            if (entry.name.endsWith('/')) {
                await fsp.mkdir(target, { recursive: true });
                continue;
            }
            await fsp.mkdir(path.dirname(target), { recursive: true });
            await fsp.writeFile(target, entry.data, { mode: entry.mode & 0o111 ? 0o755 : 0o644, flag: 'wx' });
        }
        const skill = path.join(temporary, 'SKILL.md');
        if (!fs.existsSync(skill) || !fs.statSync(skill).isFile())
            throw new PublisherError('Marketplace package does not contain a root SKILL.md.', 'missing_skill_definition');
        try {
            await fsp.rename(temporary, destination);
            moved = true;
        }
        catch (error) {
            if (error.code === 'EEXIST' || fs.existsSync(destination))
                throw new PublisherError('A Codex Skill with this Marketplace slug already exists.', 'install_target_exists', { target_dir: destination });
            throw error;
        }
    }
    catch (error) {
        if (error instanceof PublisherError)
            throw error;
        throw new PublisherError('Marketplace Skill package could not be installed safely.', 'invalid_skill_package');
    }
    finally {
        if (!moved)
            await fsp.rm(temporary, { recursive: true, force: true }).catch(() => undefined);
    }
}
function validateEntries(entries) {
    if (entries.length > MAX_FILES)
        throw new PublisherError('Marketplace package contains too many files.', 'unsafe_skill_package');
    let totalSize = 0;
    const seen = new Set();
    for (const entry of entries) {
        if (entry.name.includes('\\') || entry.name.includes('\0'))
            throw new PublisherError('Marketplace package contains an unsafe file path.', 'unsafe_skill_package');
        const parts = entry.name.split('/');
        const normalizedParts = entry.name.endsWith('/') ? parts.slice(0, -1) : parts;
        if (!normalizedParts.length || normalizedParts.some((part) => !part || part === '.' || part === '..') || entry.name.startsWith('/'))
            throw new PublisherError('Marketplace package contains an unsafe file path.', 'unsafe_skill_package');
        const collision = normalizedParts.join('/').toLowerCase();
        if (seen.has(collision))
            throw new PublisherError('Marketplace package contains duplicate file paths.', 'unsafe_skill_package');
        seen.add(collision);
        const type = entry.mode & 0o170000;
        if (type === 0o120000)
            throw new PublisherError('Marketplace package contains a symbolic link.', 'unsafe_skill_package');
        if (![0, 0o100000, 0o040000].includes(type))
            throw new PublisherError('Marketplace package contains an unsupported file type.', 'unsafe_skill_package');
        totalSize += entry.data.length;
        if (entry.data.length > MAX_UNCOMPRESSED_BYTES || totalSize > MAX_UNCOMPRESSED_BYTES)
            throw new PublisherError('Marketplace package exceeds the extraction size limit.', 'unsafe_skill_package');
    }
    return entries;
}
function installContract(response) {
    if (isRecord(response.data))
        return response.data;
    throw new PublisherError('Marketplace install response is invalid.', 'invalid_marketplace_response');
}
function requirementsFromSources(latest, publisher, metadata) {
    const latestPublisher = record(record(latest.metadata).publisher);
    const requirements = record(latestPublisher.requirements ?? publisher.requirements ?? metadata.requirements);
    const result = [];
    for (const [kind, key] of [['secret', 'secrets'], ['env', 'env']]) {
        const values = requirements[key];
        if (!Array.isArray(values))
            continue;
        for (const value of values.filter(isRecord)) {
            const name = firstString(value, 'name', 'key');
            if (name)
                result.push({ kind, name, purpose: firstString(value, 'purpose', 'description'), required: value.required !== false });
        }
    }
    return result;
}
function safeDestination(root, slug) {
    const resolvedRoot = path.resolve(root);
    const destination = path.resolve(resolvedRoot, slug);
    if (path.dirname(destination) !== resolvedRoot)
        throw new PublisherError('Marketplace Skill install target escapes the Codex skills directory.', 'unsafe_install_target');
    return destination;
}
function validateItemId(value) {
    if (!ITEM_ID_RE.test(String(value ?? '').trim()))
        throw new PublisherError('Marketplace item ID must be a UUID.', 'invalid_item_id');
}
function record(value) {
    return isRecord(value) ? value : {};
}
function firstString(source, ...keys) {
    for (const key of keys)
        if (typeof source[key] === 'string' && String(source[key]).trim())
            return String(source[key]).trim();
    return '';
}
function strings(value) {
    if (!Array.isArray(value))
        return [];
    return [...new Set(value.filter((item) => typeof item === 'string' && Boolean(item.trim())).map((item) => item.trim()))];
}
function firstPositiveInt(...values) {
    for (const value of values) {
        const parsed = Number(value);
        if (Number.isInteger(parsed) && parsed > 0)
            return parsed;
    }
    return null;
}
function firstNonnegativeInt(...values) {
    for (const value of values) {
        const parsed = Number(value);
        if (Number.isInteger(parsed) && parsed >= 0)
            return parsed;
    }
    return 0;
}
